"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[75986],{47478:e=>{e.exports=JSON.parse('{"functions":[{"name":"find","desc":"The gun-rig weapon `model` holds: its `GunJoint`, Handle, container, hold name and\\ngrip point (a Tool\'s `Grip`; a pirate gun\'s `Grip` attribute). nil when none.","params":[{"name":"model","desc":"","lua_type":"Model"}],"returns":[{"desc":"","lua_type":"Motor6D?"},{"desc":"","lua_type":"BasePart?"},{"desc":"","lua_type":"Instance?"},{"desc":"","lua_type":"string?"},{"desc":"","lua_type":"CFrame?"}],"function_type":"static","source":{"line":61,"path":"src/StarterPlayer/StarterPlayerScripts/GunRigDriver.luau"}},{"name":"Refresh","desc":"Re-reads the pose (`eff`: the saved pose, or the editor preview for the local player)\\nand rebuilds the arm chains. The local player\'s rest frames and size follow `eff`\\nat once (the server only knows the saved pose).","params":[{"name":"d","desc":"","lua_type":"Driver"},{"name":"eff","desc":"","lua_type":"WeaponPose.Effective"}],"returns":[],"function_type":"static","source":{"line":88,"path":"src/StarterPlayer/StarterPlayerScripts/GunRigDriver.luau"}},{"name":"new","desc":"A driver for the gun-rig weapon `model` holds, or nil (no gun rig, or arms that cannot\\nbe measured). Turns the arms\' BallSocketConstraints off until `Destroy`.","params":[{"name":"model","desc":"","lua_type":"Model"},{"name":"animator","desc":"","lua_type":"Animator"},{"name":"isLocal","desc":"","lua_type":"boolean"},{"name":"eff","desc":"","lua_type":"WeaponPose.Effective"}],"returns":[{"desc":"","lua_type":"Driver?\\n"}],"function_type":"static","source":{"line":123,"path":"src/StarterPlayer/StarterPlayerScripts/GunRigDriver.luau"}},{"name":"Step","desc":"One frame, after `AimPose.Step`. `armTurn` = `AimPose.ArmTurn` (UpperTorso space).\\n`speed` (ground speed), `camTurn` (local camera turn rate, rad/s) and `sprinting`\\ndrive the code layer (`WeaponFeel`), put on the gun about its grip point.","params":[{"name":"d","desc":"","lua_type":"Driver"},{"name":"dt","desc":"","lua_type":"number"},{"name":"armTurn","desc":"","lua_type":"CFrame"},{"name":"speed","desc":"","lua_type":"number"},{"name":"camTurn","desc":"","lua_type":"Vector2?"},{"name":"sprinting","desc":"","lua_type":"boolean"}],"returns":[],"function_type":"static","source":{"line":185,"path":"src/StarterPlayer/StarterPlayerScripts/GunRigDriver.luau"}},{"name":"Destroy","desc":"Gives the arms back to the animation: restores the BallSocketConstraints.","params":[{"name":"d","desc":"","lua_type":"Driver"}],"returns":[],"function_type":"static","source":{"line":242,"path":"src/StarterPlayer/StarterPlayerScripts/GunRigDriver.luau"}}],"properties":[],"types":[],"name":"GunRigDriver","desc":"Per-rig hands and gun of a gun-rig weapon (`GunRig`), for any visible rig (players\\nand pirates). Owned and stepped by `AimPoseController`, after `AimPose.Step`, in\\n`RunService.PreSimulation`. One owner per joint, every frame:\\n- the gun joint (`UpperTorso.GunJoint`): the animation\'s Transform, with the aim\'s\\n  arm turn and the code layer (`WeaponFeel`) put on top;\\n- the arms: `ArmIK`, the right hand on the gun\'s grip point (`Tool.Grip`), the left\\n  hand on the gun\'s `LeftHandIK` target (slid back toward the right hand when a short\\n  arm cannot reach it). One-hand weapons IK the left hand only while they reload.\\nEverything is solved in UpperTorso space from joint frames, so the hands never lag\\nthe gun. While it holds a gun, the arms\' BallSocketConstraints are off (their limits\\nstop the hand short). The local player\'s driver also keeps the gun\'s rest frames on\\nthe unsaved pose-editor preview.","realm":["Client"],"source":{"line":19,"path":"src/StarterPlayer/StarterPlayerScripts/GunRigDriver.luau"}}')}}]);